package dev.rodrigosambade.sprint;
import java.time.Duration;import java.util.*;import java.util.concurrent.*;import java.util.random.RandomGenerator;
public final class SprintRace{
 public record Athlete(String name,int bib){} public record Result(Athlete athlete,double seconds){}
 private final List<Athlete>athletes;private final RandomGenerator random;public SprintRace(List<Athlete>athletes,RandomGenerator random){if(athletes.isEmpty())throw new IllegalArgumentException();this.athletes=List.copyOf(athletes);this.random=Objects.requireNonNull(random);}
 public List<Result>run(Duration minimum,Duration maximum)throws InterruptedException{if(minimum.isNegative()||maximum.compareTo(minimum)<0)throw new IllegalArgumentException();CountDownLatch gun=new CountDownLatch(1);Queue<Result>results=new ConcurrentLinkedQueue<>();long lo=minimum.toMillis(),hi=maximum.toMillis();try(var ex=Executors.newFixedThreadPool(athletes.size())){List<Future<?>>fs=new ArrayList<>();for(Athlete a:athletes){long delay=lo+(hi==lo?0:random.nextLong(hi-lo+1));fs.add(ex.submit(()->{try{gun.await();long start=System.nanoTime();Thread.sleep(delay);double sec=(System.nanoTime()-start)/1_000_000_000d;results.add(new Result(a,sec));}catch(InterruptedException e){Thread.currentThread().interrupt();}}));}System.out.println("Preparados");Thread.sleep(Math.min(100,Math.max(0,lo/10)));System.out.println("Listos");Thread.sleep(Math.min(100,Math.max(0,lo/10)));System.out.println("¡Ya!");gun.countDown();for(Future<?>f:fs)try{f.get();}catch(ExecutionException e){throw new IllegalStateException(e.getCause());}}return results.stream().sorted(Comparator.comparingDouble(Result::seconds)).toList();}
 public static void main(String[]args)throws Exception{List<Athlete>as=new ArrayList<>();for(int i=1;i<=8;i++)as.add(new Athlete("Atleta "+i,i));for(Result r:new SprintRace(as,RandomGenerator.getDefault()).run(Duration.ofMillis(90),Duration.ofMillis(120)))System.out.printf(Locale.ROOT,"%d tarda %.3f s%n",r.athlete().bib(),r.seconds());}
}
